MIN_SNOW_DEPTH = 20
MAX_WIND_SPEED = 30
MAX_ICE_THICKNESS = 2


def is_safe_trail(snow_depth, wind_speed, ice_thickness):
    return (
        snow_depth >= MIN_SNOW_DEPTH
        and wind_speed < MAX_WIND_SPEED
        and ice_thickness < MAX_ICE_THICKNESS
    )


def safety_score(snow_depth, wind_speed):
    return snow_depth - wind_speed


def validate_condition(condition, trail_index):
    if len(condition) != 3:
        raise ValueError(
            "trail %d must have snow depth, wind speed and ice thickness" % trail_index
        )
    for measured_value in condition:
        if not isinstance(measured_value, (int, float)):
            raise TypeError("trail %d has a non-numeric measurement" % trail_index)
        if measured_value < 0:
            raise ValueError("trail %d has a negative measurement" % trail_index)


def evaluate(conditions):
    score_list = []
    for trail_index, condition in enumerate(conditions):
        validate_condition(condition, trail_index)
        snow_depth, wind_speed, ice_thickness = condition
        if is_safe_trail(snow_depth, wind_speed, ice_thickness):
            score_list.append(safety_score(snow_depth, wind_speed))
    return score_list


def summarize_scores(score_list):
    if not score_list:
        return {"safe_count": 0, "best_score": None, "average_score": None}
    total_score = sum(score_list)
    return {
        "safe_count": len(score_list),
        "best_score": max(score_list),
        "average_score": total_score / len(score_list),
    }


def format_report(conditions, score_list):
    report_lines = []
    for trail_index, condition in enumerate(conditions):
        snow_depth, wind_speed, ice_thickness = condition
        trail_status = (
            "SAFE" if is_safe_trail(snow_depth, wind_speed, ice_thickness) else "CLOSED"
        )
        report_lines.append(
            "Trail %d: snow=%sin wind=%smph ice=%sin -> %s"
            % (trail_index + 1, snow_depth, wind_speed, ice_thickness, trail_status)
        )
    score_summary = summarize_scores(score_list)
    report_lines.append("Safe trails: %d" % score_summary["safe_count"])
    if score_summary["best_score"] is not None:
        report_lines.append("Best score: %s" % score_summary["best_score"])
        report_lines.append("Average score: %.2f" % score_summary["average_score"])
    return "\n".join(report_lines)


def main():
    trail_conditions = [
        (30, 15, 1),
        (18, 10, 0.5),
        (40, 35, 1),
        (25, 20, 3),
        (22, 5, 1.5),
    ]
    score_list = evaluate(trail_conditions)
    print(format_report(trail_conditions, score_list))
    print("Scores: %s" % score_list)


if __name__ == "__main__":
    main()

