import math

BASE_FOOD_FRACTION = 0.05
MINIMUM_FOOD_KG = 2.0


def validate_animal_entry(animal_entry, entry_index):
    if len(animal_entry) != 2:
        raise ValueError("animal %d must be a (weight, multiplier) pair" % entry_index)
    animal_weight, metabolic_rate = animal_entry
    if animal_weight < 0:
        raise ValueError("animal %d has a negative weight" % entry_index)
    if metabolic_rate < 0:
        raise ValueError("animal %d has a negative metabolic rate" % entry_index)
    return float(animal_weight), float(metabolic_rate)


def food_for_animal(animal_weight, metabolic_rate):
    base_requirement = animal_weight * BASE_FOOD_FRACTION
    specific_amount = base_requirement * metabolic_rate
    if specific_amount < MINIMUM_FOOD_KG:
        return MINIMUM_FOOD_KG
    return specific_amount


def portion_list(animals):
    portion_values = []
    for entry_index, animal_entry in enumerate(animals):
        animal_weight, metabolic_rate = validate_animal_entry(animal_entry, entry_index)
        portion_values.append(food_for_animal(animal_weight, metabolic_rate))
    return portion_values


def feed(animals):
    total_food = sum(portion_list(animals))
    return math.floor(total_food)


def build_feeding_report(animals):
    portion_values = portion_list(animals)
    report_lines = []
    for entry_index, portion_amount in enumerate(portion_values):
        animal_weight, metabolic_rate = animals[entry_index]
        was_topped_up = portion_amount == MINIMUM_FOOD_KG
        line_suffix = " (minimum applied)" if was_topped_up else ""
        report_lines.append(
            "animal %d: %.1f kg at rate %.2f -> %.2f kg%s"
            % (entry_index + 1, animal_weight, metabolic_rate, portion_amount, line_suffix)
        )
    if portion_values:
        heaviest_portion = max(portion_values)
        average_portion = sum(portion_values) / len(portion_values)
        report_lines.append("largest portion: %.2f kg" % heaviest_portion)
        report_lines.append("average portion: %.2f kg" % average_portion)
    report_lines.append("total food ordered: %d kg" % feed(animals))
    return "\n".join(report_lines)


def main():
    herd_data = [
        (100, 1.5),
        (20, 1.0),
        (450, 0.8),
        (5, 2.5),
    ]
    print(build_feeding_report(herd_data))
    single_animal = [(100, 1.5)]
    print("single animal check: %d" % feed(single_animal))


if __name__ == "__main__":
    main()

