BASE_RENEWAL_FEE = 100
LOYALTY_DISCOUNT = 20
NEW_MEMBER_FEE = 15
LOYALTY_THRESHOLD_MONTHS = 60
NEW_MEMBER_THRESHOLD_MONTHS = 12


def validate_months(months_registered):
    """Return the membership duration as an int, rejecting invalid values."""
    if isinstance(months_registered, bool) or not isinstance(months_registered, int):
        raise TypeError("membership duration must be an integer number of months")
    if months_registered < 0:
        raise ValueError("membership duration cannot be negative")
    return months_registered


def member_fee(months_registered):
    """Renewal fee owed by a single member."""
    total_fee = BASE_RENEWAL_FEE
    if months_registered > LOYALTY_THRESHOLD_MONTHS:
        total_fee -= LOYALTY_DISCOUNT
    elif months_registered < NEW_MEMBER_THRESHOLD_MONTHS:
        total_fee += NEW_MEMBER_FEE
    return total_fee


def renewals(members):
    """Total renewal fees expected from every member in the list."""
    total_fees = 0
    for months_registered in members:
        total_fees += member_fee(validate_months(months_registered))
    return total_fees


def fee_breakdown(members):
    """Pair each membership duration with its individual fee."""
    return [(validate_months(months), member_fee(months)) for months in members]


def summarize_renewals(members):
    """Human readable report of the individual fees and their total."""
    breakdown_lines = []
    for months_registered, fee_owed in fee_breakdown(members):
        if months_registered > LOYALTY_THRESHOLD_MONTHS:
            fee_label = "loyalty discount"
        elif months_registered < NEW_MEMBER_THRESHOLD_MONTHS:
            fee_label = "new member fee"
        else:
            fee_label = "standard rate"
        breakdown_lines.append(
            "{:>4} months: ${:>4}  ({})".format(months_registered, fee_owed, fee_label)
        )
    breakdown_lines.append("{:>13}  ${:>4}".format("total:", renewals(members)))
    return "\n".join(breakdown_lines)


def main():
    membership_groups = {
        "example group": [6, 24, 72],
        "long standing": [61, 84, 120, 60],
        "mixed intake": [0, 11, 12, 59, 61],
    }
    expected_totals = []
    for group_name, member_months in membership_groups.items():
        print("{}:".format(group_name))
        print(summarize_renewals(member_months))
        expected_totals.append(renewals(member_months))
        print()
    grand_total = sum(expected_totals)
    print("Expected income across all groups: ${}".format(grand_total))


if __name__ == "__main__":
    main()

