def validate_route(route_entry):
    if len(route_entry) != 3:
        raise ValueError(f"route entry must have three fields: {route_entry!r}")
    zone_name, fill_level, center_distance = route_entry
    if not isinstance(fill_level, (int, float)) or not isinstance(center_distance, (int, float)):
        raise TypeError(f"fill level and distance must be numeric for zone {zone_name!r}")
    if fill_level < 0 or fill_level > 100:
        raise ValueError(f"fill level out of range for zone {zone_name!r}: {fill_level}")
    if center_distance < 0:
        raise ValueError(f"distance must not be negative for zone {zone_name!r}")
    return zone_name, fill_level, center_distance


def base_truck_count(fill_level):
    if fill_level > 80:
        return 2
    if fill_level >= 50:
        return 1
    return 0


def extra_truck_count(fill_level, center_distance):
    if center_distance > 10 and fill_level > 70:
        return 1
    return 0


def optimize(routes):
    max_trucks_per_zone = 4
    dispatch_plan = []
    for route_entry in routes:
        zone_name, fill_level, center_distance = validate_route(route_entry)
        base_count = base_truck_count(fill_level)
        extra_count = extra_truck_count(fill_level, center_distance)
        total_count = min(base_count + extra_count, max_trucks_per_zone)
        dispatch_plan.append((zone_name, total_count))
    return dispatch_plan


def summarize_plan(dispatch_plan):
    total_trucks = 0
    highest_count = 0
    idle_zones = []
    for zone_name, truck_count in dispatch_plan:
        total_trucks += truck_count
        if truck_count > highest_count:
            highest_count = truck_count
        if truck_count == 0:
            idle_zones.append(zone_name)
    busiest_zones = [zone_name for zone_name, truck_count in dispatch_plan if truck_count == highest_count]
    return total_trucks, idle_zones, busiest_zones


def format_report(dispatch_plan):
    total_trucks, idle_zones, busiest_zones = summarize_plan(dispatch_plan)
    report_lines = ["Zone dispatch plan", "------------------"]
    for zone_name, truck_count in dispatch_plan:
        truck_word = "truck" if truck_count == 1 else "trucks"
        report_lines.append(f"{zone_name:<10} {truck_count} {truck_word}")
    report_lines.append(f"Total trucks dispatched: {total_trucks}")
    if idle_zones:
        report_lines.append(f"Zones skipped this cycle: {', '.join(idle_zones)}")
    if total_trucks:
        report_lines.append(f"Highest demand: {', '.join(busiest_zones)}")
    return "\n".join(report_lines)


