    measured_routes = [
        ("North", 85, 12),
        ("South", 64, 4),
        ("East", 95, 18),
        ("West", 31, 22),
        ("Central", 72, 11),
    ]
    daily_plan = optimize(measured_routes)
    print(format_report(daily_plan))


if __name__ == "__main__":
    main()

