RARE_LETTERS = ("z", "q")
RARE_LETTER_BONUS = 10


def compute_base_score(word):
    """Base score is twice the number of characters in the word."""
    return len(word) * 2


def has_rare_letter(word):
    """True when the word contains one of the rare tournament letters."""
    lowered_word = word.lower()
    return any(rare_letter in lowered_word for rare_letter in RARE_LETTERS)


def compute_word_total(word, word_multiplier):
    """Adjusted base score for a single word, scaled by its multiplier."""
    adjusted_base = compute_base_score(word)
    if has_rare_letter(word):
        adjusted_base += RARE_LETTER_BONUS
    return adjusted_base * word_multiplier


def validate_inputs(words, bonuses):
    if len(words) != len(bonuses):
        raise ValueError(
            "each word needs exactly one bonus: got {0} words and {1} bonuses".format(
                len(words), len(bonuses)
            )
        )
    for word_index, word in enumerate(words):
        if not isinstance(word, str):
            raise TypeError("word at position {0} is not a string".format(word_index))
    for bonus_index, bonus_value in enumerate(bonuses):
        if not isinstance(bonus_value, int) or isinstance(bonus_value, bool):
            raise TypeError(
                "bonus at position {0} is not an integer".format(bonus_index)
            )


def score(words, bonuses):
    """Total match score for a list of words and their multipliers."""
    validate_inputs(words, bonuses)
    match_total = 0
    for word, word_multiplier in zip(words, bonuses):
        match_total += compute_word_total(word, word_multiplier)
    return match_total


def build_score_report(words, bonuses):
    """Per-word breakdown lines followed by a final match total line."""
    validate_inputs(words, bonuses)
    report_lines = []
    for word, word_multiplier in zip(words, bonuses):
        base_value = compute_base_score(word)
        bonus_marker = "rare" if has_rare_letter(word) else "plain"
        word_total = compute_word_total(word, word_multiplier)
        report_lines.append(
            "{0:<10} base={1:>3} {2:<5} x{3} = {4}".format(
                word, base_value, bonus_marker, word_multiplier, word_total
            )
        )
    report_lines.append("match score: {0}".format(score(words, bonuses)))
    return report_lines


def main():
    sample_rounds = [
        (["quiz"], [3]),
        (["hello", "zebra", "apple"], [1, 2, 4]),
        (["jazz", "queen", "tree", "quartz"], [2, 3, 1, 5]),
    ]
    for round_number, (round_words, round_bonuses) in enumerate(sample_rounds, start=1):
        print("Round {0}".format(round_number))
        for report_line in build_score_report(round_words, round_bonuses):
            print("  " + report_line)


if __name__ == "__main__":
    main()

