SEAM_ALLOWANCE_CM = 5.0


def washed_length(base_length, shrinkage_percentage):
    """Grow the base length by its shrinkage factor."""
    return base_length * (1.0 + shrinkage_percentage)


def cut_width(base_width, shrinkage_percentage):
    """Grow the base width by its shrinkage factor and add the seam allowance."""
    return base_width * (1.0 + shrinkage_percentage) + SEAM_ALLOWANCE_CM


def validate_pattern(pattern_record):
    """Unpack one raw record into (identifier, length, width, shrinkage)."""
    if len(pattern_record) != 4:
        raise ValueError("each pattern needs an id, length, width and shrinkage")
    pattern_identifier, base_length, base_width, shrinkage_percentage = pattern_record
    if not isinstance(pattern_identifier, str) or not pattern_identifier.strip():
        raise ValueError("pattern identifier must be a non-empty string")
    for label, measured_value in (("length", base_length), ("width", base_width)):
        if measured_value <= 0:
            raise ValueError("%s of %s must be positive" % (label, pattern_identifier))
    if shrinkage_percentage < 0:
        raise ValueError("shrinkage of %s cannot be negative" % pattern_identifier)
    return (
        pattern_identifier.strip(),
        float(base_length),
        float(base_width),
        float(shrinkage_percentage),
    )


def estimate(patterns):
    """Return [(identifier, required_area_in_square_cm), ...] for every pattern."""
    estimate_results = []
    for pattern_record in patterns:
        pattern_identifier, base_length, base_width, shrinkage_percentage = validate_pattern(pattern_record)
        final_length = washed_length(base_length, shrinkage_percentage)
        final_width = cut_width(base_width, shrinkage_percentage)
        required_area = final_length * final_width
        estimate_results.append((pattern_identifier, required_area))
    return estimate_results


def format_report(estimate_results):
    """Build an aligned text report plus a total line for the cutting table."""
    if not estimate_results:
        return "no patterns to cut"
    max_name_width = max(len(pattern_identifier) for pattern_identifier, _area in estimate_results)
    report_lines = []
    total_required_area = 0.0
    for pattern_identifier, required_area in estimate_results:
        total_required_area += required_area
        report_lines.append(
            "%-*s %12.1f cm2" % (max_name_width, pattern_identifier, required_area)
        )
    report_lines.append("-" * (max_name_width + 17))
    report_lines.append("%-*s %12.1f cm2" % (max_name_width, "TOTAL", total_required_area))
    return "\n".join(report_lines)


def main():
