        ("Shirt", 100, 50, 0.1),
        ("Trousers", 110, 45, 0.05),
        ("Pocket", 18, 16, 0.0),
    ]
    estimate_results = estimate(pattern_list)
    for pattern_identifier, required_area in estimate_results:
        print((pattern_identifier, round(required_area, 1)))
    print(format_report(estimate_results))


