vibrationFrequency = 300.0


def coreFactor(scaleLength):
    """Return the squared product of twice the scale length and the frequency."""
    doubledLength = 2.0 * scaleLength
    rawFactor = doubledLength * vibrationFrequency
    return rawFactor * rawFactor


def validateProfile(stringProfile):
    """Unpack and check one (identifier, unit weight, scale length) tuple."""
    if len(stringProfile) != 3:
        raise ValueError("each string profile needs 3 fields: %r" % (stringProfile,))
    stringId, unitWeight, scaleLength = stringProfile
    if not isinstance(stringId, str) or not stringId.strip():
        raise ValueError("string identifier must be a non-empty text label")
    if unitWeight <= 0:
        raise ValueError("unit weight for %s must be positive" % stringId)
    if scaleLength <= 0:
        raise ValueError("scale length for %s must be positive" % stringId)
    return stringId.strip(), float(unitWeight), float(scaleLength)


def tension(strings):
    """Compute the required tension for every string profile in the list."""
    tensionTable = []
    for stringProfile in strings:
        stringId, unitWeight, scaleLength = validateProfile(stringProfile)
        rawTension = coreFactor(scaleLength) * unitWeight
        tensionTable.append((stringId, round(rawTension, 4)))
    return tensionTable


def tensionSummary(tensionTable):
    """Return the heaviest entry, lightest entry and mean of a computed table."""
    tensionValues = [entryValue for entryLabel, entryValue in tensionTable]
    maxEntry = max(tensionTable, key=lambda tableEntry: tableEntry[1])
    minEntry = min(tensionTable, key=lambda tableEntry: tableEntry[1])
    averageTension = sum(tensionValues) / len(tensionValues)
    return maxEntry, minEntry, round(averageTension, 4)


def formatReport(tensionTable):
    """Build a printable, aligned report of the tension table."""
    if not tensionTable:
        return "no string profiles supplied"
    labelWidth = max(len(entryLabel) for entryLabel, entryValue in tensionTable)
    reportLines = ["%-*s  %12s" % (labelWidth, "STRING", "TENSION")]
    for stringId, requiredTension in tensionTable:
        reportLines.append("%-*s  %12.3f" % (labelWidth, stringId, requiredTension))
    maxEntry, minEntry, averageTension = tensionSummary(tensionTable)
    reportLines.append("heaviest: %s (%.3f)" % (maxEntry[0], maxEntry[1]))
    reportLines.append("lightest: %s (%.3f)" % (minEntry[0], minEntry[1]))
    reportLines.append("average : %.3f" % averageTension)
    return "\n".join(reportLines)


def main():
    stringSet = [
        ("E", 0.005, 0.6),
        ("A", 0.0075, 0.6),
        ("D", 0.011, 0.635),
        ("G", 0.018, 0.648),
    ]
    computedTable = tension(stringSet)
    print(formatReport(computedTable))


if __name__ == "__main__":
    main()

