ROOM_TEMPERATURE = 20.0


def validate_stage(raw_stage):
    if len(raw_stage) != 3:
        raise ValueError("each stage needs an id, a target temperature and a heating rate")
    stage_id, target_temperature, heating_rate = raw_stage
    if not isinstance(stage_id, str) or not stage_id.strip():
        raise ValueError("stage identifier must be a non-empty string")
    target_value = float(target_temperature)
    rate_value = float(heating_rate)
    if rate_value <= 0:
        raise ValueError("heating rate for %s must be positive" % stage_id)
    return stage_id.strip(), target_value, rate_value


def schedule(stages):
    previous_temperature = ROOM_TEMPERATURE
    stage_plan = []
    for raw_stage in stages:
        stage_id, target_temperature, heating_rate = validate_stage(raw_stage)
        temperature_delta = target_temperature - previous_temperature
        stage_duration = temperature_delta / heating_rate
        stage_plan.append((stage_id, stage_duration))
        previous_temperature = target_temperature
    return stage_plan


def total_duration(stage_plan):
    running_total = 0.0
    for stage_id, stage_duration in stage_plan:
        running_total += stage_duration
    return running_total


def longest_stage(stage_plan):
    slowest_id = None
    max_duration = 0.0
    for stage_id, stage_duration in stage_plan:
        if slowest_id is None or stage_duration > max_duration:
            slowest_id = stage_id
            max_duration = stage_duration
    return slowest_id, max_duration


def format_duration(stage_duration):
    whole_hours = int(stage_duration)
    leftover_minutes = round((stage_duration - whole_hours) * 60)
    if leftover_minutes == 60:
        whole_hours += 1
        leftover_minutes = 0
    return "%dh%02dm" % (whole_hours, leftover_minutes)


def build_report(stage_plan):
    report_lines = []
    elapsed_hours = 0.0
    for stage_id, stage_duration in stage_plan:
        elapsed_hours += stage_duration
        report_lines.append(
            "%-10s %8s  (done at %s)"
            % (stage_id, format_duration(stage_duration), format_duration(elapsed_hours))
        )
    slowest_id, slowest_duration = longest_stage(stage_plan)
    if slowest_id is not None:
        report_lines.append("longest stage: %s (%s)" % (slowest_id, format_duration(slowest_duration)))
    report_lines.append("total cycle: %s" % format_duration(total_duration(stage_plan)))
    return "\n".join(report_lines)


def main():
    firing_stages = [
        ("Warmup", 220, 100),
        ("Bisque", 1000, 150),
        ("Soak", 1000, 150),
        ("Glaze", 1250, 80),
    ]
    print(build_report(schedule(firing_stages)))


if __name__ == "__main__":
    main()

