def validate_record(record_entry):
    if len(record_entry) != 3:
        raise ValueError("each record needs an identifier, scratch count and noise level")
    record_id, scratch_count, noise_level = record_entry
    if not isinstance(record_id, str) or not record_id:
        raise ValueError("record identifier must be a non-empty string")
    if not isinstance(scratch_count, int) or scratch_count < 0:
        raise ValueError("scratch count for %r must be a non-negative integer" % (record_id,))
    if not isinstance(noise_level, int) or not 1 <= noise_level <= 10:
        raise ValueError("noise level for %r must be between one and ten" % (record_id,))
    return record_id, scratch_count, noise_level


def is_pristine(scratch_count, noise_level):
    return scratch_count == 0 and noise_level < 3


def is_damaged(scratch_count, noise_level):
    return scratch_count > 5 or noise_level > 7


def grade_one(scratch_count, noise_level):
    if is_pristine(scratch_count, noise_level):
        return "mint"
    if is_damaged(scratch_count, noise_level):
        return "poor"
    return "good"


def grade(records):
    graded_list = []
    for record_entry in records:
        record_id, scratch_count, noise_level = validate_record(record_entry)
        graded_list.append((record_id, grade_one(scratch_count, noise_level)))
    return graded_list


def count_grades(graded_list):
    grade_tally = {"mint": 0, "good": 0, "poor": 0}
    for _record_id, grade_name in graded_list:
        grade_tally[grade_name] += 1
    return grade_tally


def format_report(graded_list):
    if not graded_list:
        return "no records appraised"
    widest_id = max(len(record_id) for record_id, _grade_name in graded_list)
    report_lines = []
    for record_id, grade_name in graded_list:
        report_lines.append("%-*s  %s" % (widest_id, record_id, grade_name))
    grade_tally = count_grades(graded_list)
    total_count = len(graded_list)
    summary_line = "%d records: %d mint, %d good, %d poor" % (
        total_count,
        grade_tally["mint"],
        grade_tally["good"],
        grade_tally["poor"],
    )
    report_lines.append("-" * len(summary_line))
    report_lines.append(summary_line)
    return "\n".join(report_lines)


def main():
    collection_records = [
        ("AbbeyRoad", 0, 2),
        ("KindOfBlue", 1, 4),
        ("RumoursWorn", 7, 5),
        ("HotelCalifornia", 0, 3),
        ("DarkSideNoisy", 2, 9),
        ("BluesBreaker", 5, 7),
    ]
    graded_list = grade(collection_records)
    print(format_report(graded_list))
    poor_ids = [record_id for record_id, grade_name in graded_list if grade_name == "poor"]
    if poor_ids:
        print("needs replacement: " + ", ".join(poor_ids))


if __name__ == "__main__":
    main()

