def climate_modifier(ambient_temperature):
    """Return the feeding multiplier implied by the ambient temperature."""
    if ambient_temperature > 25:
        return 1.2
    if ambient_temperature < 20:
        return 0.9
    return 1.0


def validate_starter(starter_record):
    """Unpack and check one starter tuple, returning normalised values."""
    if len(starter_record) != 3:
        raise ValueError("each starter needs an id, a weight and a temperature")
    starter_id, current_weight, ambient_temperature = starter_record
    if not isinstance(starter_id, str) or not starter_id.strip():
        raise ValueError("starter identifier must be a non-empty string")
    if current_weight < 0:
        raise ValueError("starter %s has a negative weight" % starter_id)
    return starter_id.strip(), float(current_weight), float(ambient_temperature)


def feed(starters):
    """Compute the feeding amount for every starter in the list."""
    feeding_plan = []
    for starter_record in starters:
        starter_id, current_weight, ambient_temperature = validate_starter(starter_record)
        base_amount = current_weight
        temperature_multiplier = climate_modifier(ambient_temperature)
        final_amount = round(base_amount * temperature_multiplier)
        feeding_plan.append((starter_id, final_amount))
    return feeding_plan


def total_flour_needed(feeding_plan):
    """Sum the flour grams required by a feeding plan."""
    return sum(final_amount for _unused_id, final_amount in feeding_plan)


def describe_conditions(ambient_temperature):
    """Human readable label for the room conditions of a starter."""
    if ambient_temperature > 25:
        return "warm room, boosted feed"
    if ambient_temperature < 20:
        return "cool room, reduced feed"
    return "ideal room, standard feed"


def build_report(starters):
    """Produce printable lines pairing each feeding amount with its reason."""
    feeding_plan = feed(starters)
    report_lines = []
    for starter_record, plan_entry in zip(starters, feeding_plan):
        _starter_id, _current_weight, ambient_temperature = validate_starter(starter_record)
        starter_id, final_amount = plan_entry
        condition_label = describe_conditions(ambient_temperature)
        report_lines.append(
            "%-10s %5d g  (%s)" % (starter_id, final_amount, condition_label)
        )
    grand_total = total_flour_needed(feeding_plan)
    report_lines.append("%-10s %5d g" % ("TOTAL", grand_total))
    return report_lines


def main():
    starter_inventory = [
        ("Rye", 100, 26),
        ("Wheat", 250, 21),
        ("Spelt", 180, 18),
        ("Kamut", 90, 30),
    ]
    feeding_plan = feed(starter_inventory)
    print(feeding_plan)
    for report_line in build_report(starter_inventory):
        print(report_line)


if __name__ == "__main__":
    main()

