import math


def compute_wind_lift(surface_area):
    return surface_area * 50


def is_stable(surface_area, tail_length):
    required_tail_length = 2 * math.sqrt(surface_area)
    return tail_length >= required_tail_length


def compute_net_force(surface_area, structural_weight):
    wind_lift = compute_wind_lift(surface_area)
    return wind_lift - structural_weight / 10


def validate_kite(kite_spec):
    if len(kite_spec) != 3:
        raise ValueError("each kite needs surface area, tail length and weight")
