def normalize_time(time_value):
    return int(time_value) if float(time_value).is_integer() else round(time_value, 2)


def validate_shells(shell_list):
    validated_shells = []
    for shell_index, shell_entry in enumerate(shell_list):
        if len(shell_entry) != 3:
            raise ValueError("shell %d must have type, radius and delay" % shell_index)
        firework_type, blast_radius, launch_delay = shell_entry
        if not isinstance(firework_type, str) or not firework_type.strip():
            raise ValueError("shell %d has an invalid firework type" % shell_index)
        if blast_radius <= 0:
            raise ValueError("shell %d has a non-positive blast radius" % shell_index)
        if launch_delay < 0:
            raise ValueError("shell %d has a negative launch delay" % shell_index)
        validated_shells.append((firework_type.strip(), blast_radius, launch_delay))
    return validated_shells


def safe_interval(blast_radius):
    return blast_radius / 10.0


def synchronize(shells):
    validated_shells = validate_shells(shells)
    if not validated_shells:
        return []
    firing_times = [0]
    previous_time = 0.0
    previous_radius = validated_shells[0][1]
    for firework_type, blast_radius, launch_delay in validated_shells[1:]:
        requested_time = previous_time + launch_delay
        earliest_safe_time = previous_time + safe_interval(previous_radius)
        actual_time = max(requested_time, earliest_safe_time)
        firing_times.append(normalize_time(actual_time))
        previous_time = actual_time
        previous_radius = blast_radius
    return firing_times


def build_schedule(shells):
    validated_shells = validate_shells(shells)
    firing_times = synchronize(validated_shells)
    schedule_rows = []
    for shell_entry, firing_time in zip(validated_shells, firing_times):
        firework_type, blast_radius, launch_delay = shell_entry
        schedule_rows.append((firing_time, firework_type, blast_radius, launch_delay))
    return schedule_rows


def format_schedule(schedule_rows):
    report_lines = ["time  shell        radius  requested offset"]
    for firing_time, firework_type, blast_radius, launch_delay in schedule_rows:
        report_lines.append("{:>4}  {:<12} {:>6}  {:>16}".format(
            firing_time, firework_type, blast_radius, launch_delay))
    total_duration = max((row[0] for row in schedule_rows), default=0)
    report_lines.append("total show length before final burst: %s s" % total_duration)
    return "\n".join(report_lines)


def main():
    show_shells = [
        ("peony", 50, 0),
        ("willow", 20, 3),
        ("chrysanthemum", 80, 1),
        ("crossette", 35, 12),
        ("brocade", 60, 2),
    ]
    print(synchronize(show_shells))
    print(format_schedule(build_schedule(show_shells)))


if __name__ == "__main__":
