def is_sound(base_width, height, wetness_percent):
    height_within_limit = height <= 2 * base_width
    wetness_in_range = 10 < wetness_percent < 30
    return height_within_limit and wetness_in_range


def approximate_volume(base_width, height):
    return base_width * base_width * height


def validate_tower(tower_spec):
    if len(tower_spec) != 3:
        raise ValueError("each tower needs base width, height and wetness: %r" % (tower_spec,))
    base_width, height, wetness_percent = tower_spec
    if base_width <= 0 or height <= 0:
        raise ValueError("base width and height must be positive: %r" % (tower_spec,))
    if not 0 <= wetness_percent <= 100:
        raise ValueError("wetness percentage out of range: %r" % (tower_spec,))
    return base_width, height, wetness_percent


def assess(towers):
    total_volume = 0
    for tower_spec in towers:
        base_width, height, wetness_percent = validate_tower(tower_spec)
        if is_sound(base_width, height, wetness_percent):
            total_volume += approximate_volume(base_width, height)
    return total_volume


def describe_tower(tower_spec):
    base_width, height, wetness_percent = validate_tower(tower_spec)
    if is_sound(base_width, height, wetness_percent):
        volume_text = "%d cubic inches" % approximate_volume(base_width, height)
        verdict_text = "sound, " + volume_text
    else:
        failure_reasons = []
        if height > 2 * base_width:
            failure_reasons.append("too tall for its base")
        if not 10 < wetness_percent < 30:
            failure_reasons.append("wetness %d%% outside 10-30" % wetness_percent)
        verdict_text = "unsound (" + "; ".join(failure_reasons) + ")"
    return "%2dx%2d at %3d%%: %s" % (base_width, height, wetness_percent, verdict_text)


def build_report(towers):
    report_lines = [describe_tower(tower_spec) for tower_spec in towers]
    sound_count = sum(1 for tower_spec in towers if is_sound(*validate_tower(tower_spec)))
    report_lines.append("%d of %d towers sound" % (sound_count, len(towers)))
    report_lines.append("total sound volume: %d cubic inches" % assess(towers))
    return "\n".join(report_lines)


def main():
    beach_towers = [
        (10, 15, 20),
        (8, 20, 25),
        (12, 24, 30),
        (6, 6, 15),
        (14, 10, 9),
    ]
    print(build_report(beach_towers))


if __name__ == "__main__":
    main()

