def validate_jam_record(jam_record, record_index):
    if not isinstance(jam_record, tuple) or len(jam_record) != 3:
        raise ValueError(f"jam {record_index}: expected a 3-tuple, got {jam_record!r}")
    blockers_passed, lap_count, went_to_box = jam_record
    if not isinstance(blockers_passed, int) or isinstance(blockers_passed, bool):
        raise ValueError(f"jam {record_index}: blockers passed must be an int")
    if not isinstance(lap_count, int) or isinstance(lap_count, bool):
        raise ValueError(f"jam {record_index}: lap count must be an int")
    if not isinstance(went_to_box, bool):
        raise ValueError(f"jam {record_index}: penalty flag must be a bool")
    if blockers_passed < 0 or lap_count < 0:
        raise ValueError(f"jam {record_index}: counts must not be negative")
    return blockers_passed, lap_count, went_to_box


def score_single_jam(blockers_passed, lap_count, went_to_box):
    if lap_count < 2:
        raw_points = 0
    else:
        raw_points = blockers_passed
    if went_to_box:
        return raw_points // 2
    return raw_points


def tally(jams):
    total_points = 0
    penalty_count = 0
    for record_index, jam_record in enumerate(jams, start=1):
        blockers_passed, lap_count, went_to_box = validate_jam_record(jam_record, record_index)
        total_points += score_single_jam(blockers_passed, lap_count, went_to_box)
        if went_to_box:
            penalty_count += 1
    return total_points, penalty_count


def per_jam_breakdown(jams):
    breakdown_rows = []
    for record_index, jam_record in enumerate(jams, start=1):
        blockers_passed, lap_count, went_to_box = validate_jam_record(jam_record, record_index)
        jam_points = score_single_jam(blockers_passed, lap_count, went_to_box)
        breakdown_rows.append((record_index, jam_points, went_to_box))
    return breakdown_rows


def format_report(jams):
    report_lines = []
    for jam_number, jam_points, went_to_box in per_jam_breakdown(jams):
        box_note = " (box trip)" if went_to_box else ""
        report_lines.append(f"Jam {jam_number}: {jam_points} point(s){box_note}")
    total_points, penalty_count = tally(jams)
    report_lines.append(f"Total: {total_points} point(s) over {len(jams)} jam(s)")
    report_lines.append(f"Penalty box trips: {penalty_count}")
    return "\n".join(report_lines)


def main():
    sample_bouts = {
        "Rose City": [(4, 2, False), (3, 1, False), (6, 3, True)],
        "Gotham": [(0, 1, True), (5, 2, False), (7, 4, True), (2, 2, False)],
    }
    best_team_name = None
    best_total_points = -1
    for team_name, jam_records in sample_bouts.items():
        print(f"== {team_name} ==")
        print(format_report(jam_records))
        team_points, _penalties = tally(jam_records)
        if team_points > best_total_points:
            best_total_points = team_points
            best_team_name = team_name
        print()
    print(f"Leading team: {best_team_name} with {best_total_points} point(s)")


if __name__ == "__main__":
    main()

