def normalize_trick_name(raw_name):
    return " ".join(str(raw_name).strip().lower().split())


def parse_sequence(raw_sequence):
    parsed_tricks = []
    for trick_entry in raw_sequence:
        trick_name, base_difficulty = trick_entry
        parsed_tricks.append((normalize_trick_name(trick_name), float(base_difficulty)))
    return parsed_tricks


def sequence_multiplier(parsed_tricks):
    final_multiplier = 1.0
    if len(parsed_tricks) > long_sequence_length:
        final_multiplier += length_bonus
    trick_names = [trick_name for trick_name, _difficulty in parsed_tricks]
    if pedal_grab_name in trick_names:
        final_multiplier += pedal_grab_bonus
    return final_multiplier


def sequence_score(raw_sequence):
    parsed_tricks = parse_sequence(raw_sequence)
    base_total = sum(difficulty for _trick_name, difficulty in parsed_tricks)
    return base_total * sequence_multiplier(parsed_tricks)


