SLIGHT_TOLERANCE = 0.2
PERFECT_POINTS = 3
SLIGHT_POINTS = 1
STREAK_BONUS_POINTS = 5
MIN_STREAK_LENGTH = 3


def validate_step(raw_step):
    if len(raw_step) != 3:
        raise ValueError("each step needs a type, an intended beat and an actual beat")
    step_type, intended_beat, actual_beat = raw_step
    if not isinstance(step_type, str) or not step_type.strip():
        raise ValueError("step type must be a non-empty string")
    return step_type.strip(), float(intended_beat), float(actual_beat)


def classify_step(intended_beat, actual_beat):
    beat_offset = abs(intended_beat - actual_beat)
    if beat_offset == 0:
        return "perfect"
    if beat_offset <= SLIGHT_TOLERANCE + 1e-9:
        return "slight"
    return "miss"


def grade_points(step_grade):
    if step_grade == "perfect":
        return PERFECT_POINTS
    if step_grade == "slight":
        return SLIGHT_POINTS
    return 0


def grade_routine(steps):
    graded_steps = []
    for raw_step in steps:
        step_type, intended_beat, actual_beat = validate_step(raw_step)
        step_grade = classify_step(intended_beat, actual_beat)
        graded_steps.append((step_type, intended_beat, actual_beat, step_grade))
    return graded_steps


def streak_bonus(graded_steps):
    bonus_total = 0
    current_streak = 0
    for graded_step in list(graded_steps) + [(None, 0.0, 0.0, "miss")]:
        if graded_step[3] == "perfect":
            current_streak += 1
        else:
            if current_streak >= MIN_STREAK_LENGTH:
                bonus_total += current_streak * STREAK_BONUS_POINTS
            current_streak = 0
    return bonus_total


def score(steps):
    graded_steps = grade_routine(steps)
    base_total = sum(grade_points(graded_step[3]) for graded_step in graded_steps)
    return base_total + streak_bonus(graded_steps)


def format_report(steps):
    graded_steps = grade_routine(steps)
    report_lines = []
    for step_number, graded_step in enumerate(graded_steps, start=1):
        step_type, intended_beat, actual_beat, step_grade = graded_step
        beat_offset = abs(intended_beat - actual_beat)
        report_lines.append(
            "%2d. %-10s beat %.2f -> %.2f (off %.2f) %-7s %d pts"
            % (step_number, step_type, intended_beat, actual_beat,
               beat_offset, step_grade, grade_points(step_grade))
        )
    bonus_total = streak_bonus(graded_steps)
    report_lines.append("streak bonus: %d pts" % bonus_total)
    report_lines.append("total score: %d pts" % score(steps))
    return "\n".join(report_lines)


