BASE_SYNERGY_SCORE = 10
CONTRAST_BONUS = 3
EXCEPTIONAL_THRESHOLD = 12


def score_pairing(wine_acidity, dish_richness, has_flavor_contrast):
    raw_score = BASE_SYNERGY_SCORE - abs(wine_acidity - dish_richness)
    if has_flavor_contrast:
        raw_score += CONTRAST_BONUS
    return max(raw_score, 0)


def validate_pairing(pairing, pairing_index):
    if len(pairing) != 3:
        raise ValueError(
            "pairing %d must have exactly 3 elements" % pairing_index
        )
    wine_acidity, dish_richness, has_flavor_contrast = pairing
    if not isinstance(wine_acidity, (int, float)):
        raise TypeError("pairing %d: wine acidity must be numeric" % pairing_index)
    if not isinstance(dish_richness, (int, float)):
        raise TypeError("pairing %d: dish richness must be numeric" % pairing_index)
    if not isinstance(has_flavor_contrast, bool):
        raise TypeError("pairing %d: contrast flag must be boolean" % pairing_index)
    return wine_acidity, dish_richness, has_flavor_contrast


def rate(pairings):
    total_score = 0
    exceptional_count = 0
    pairing_count = 0
    for pairing_index, pairing in enumerate(pairings):
        wine_acidity, dish_richness, has_flavor_contrast = validate_pairing(
            pairing, pairing_index
        )
        synergy_score = score_pairing(wine_acidity, dish_richness, has_flavor_contrast)
        total_score += synergy_score
        pairing_count += 1
        if synergy_score >= EXCEPTIONAL_THRESHOLD:
            exceptional_count += 1
    if pairing_count == 0:
        return (0.0, 0)
    average_score = total_score / pairing_count
    return (average_score, exceptional_count)


def build_report(pairings):
    report_lines = []
    for wine_acidity, dish_richness, has_flavor_contrast in pairings:
        synergy_score = score_pairing(wine_acidity, dish_richness, has_flavor_contrast)
        contrast_label = "contrast" if has_flavor_contrast else "harmony"
        report_lines.append(
            "acidity %-3s richness %-3s %-8s -> %2d%s"
            % (
                wine_acidity,
                dish_richness,
                contrast_label,
                synergy_score,
                " *" if synergy_score >= EXCEPTIONAL_THRESHOLD else "",
            )
        )
    return "\n".join(report_lines)


def main():
    menu_pairings = [
        (5, 5, True),
        (8, 2, False),
        (3, 4, True),
        (9, 1, True),
        (6, 6, False),
    ]
    print(build_report(menu_pairings))
    average_score, exceptional_count = rate(menu_pairings)
    print("average synergy score: %.2f" % average_score)
    print("exceptional pairings: %d" % exceptional_count)
    print("single pairing check:", rate([(5, 5, True)]))


if __name__ == "__main__":
    main()

