    report_lines.append(
        "longest segment: {0} -> {1} ({2:.4f})".format(
            longest_index, longest_index + 1, longest_distance
        )
    )
    (left_index, right_index), closest_distance = nearest_pair(point_list)
    report_lines.append(
        "closest pair: {0} and {1} ({2:.4f})".format(
            left_index, right_index, closest_distance
        )
    )
    return "\n".join(report_lines)


