def parse_csv_line(csv_line):
    if not isinstance(csv_line, str):
        raise TypeError("csv_line must be a string")
    stripped_line = csv_line.rstrip("\r\n")
    if stripped_line == "":
        return []
    return [single_field.strip() for single_field in stripped_line.split(",")]


def parse_csv_table(line_list):
    parsed_rows = []
    for raw_line in line_list:
        parsed_rows.append(parse_csv_line(raw_line))
    return parsed_rows


def find_column_widths(row_list):
    width_list = []
    for current_row in row_list:
        for column_index, cell_value in enumerate(current_row):
            cell_width = len(cell_value)
            if column_index >= len(width_list):
                width_list.append(cell_width)
            elif cell_width > width_list[column_index]:
                width_list[column_index] = cell_width
    return width_list


def format_table(row_list):
    column_widths = find_column_widths(row_list)
    formatted_lines = []
    for current_row in row_list:
        padded_cells = []
        for column_index, cell_value in enumerate(current_row):
            padded_cells.append(cell_value.ljust(column_widths[column_index]))
        formatted_lines.append(" | ".join(padded_cells).rstrip())
    return formatted_lines


def parse_number(text_value):
    try:
        return float(text_value)
    except ValueError:
        return None


def column_total(row_list, column_index):
    running_total = 0.0
    for current_row in row_list:
        numeric_value = parse_number(current_row[column_index])
        if numeric_value is not None:
            running_total += numeric_value
    return running_total


