import math


def validate_point(candidate_point, point_label):
    if not isinstance(candidate_point, (tuple, list)):
        raise TypeError(f"{point_label} must be a tuple of three numbers")
    if len(candidate_point) != 3:
        raise ValueError(f"{point_label} must contain exactly three coordinates")
    for axis_name, axis_value in zip("xyz", candidate_point):
        if isinstance(axis_value, bool) or not isinstance(axis_value, (int, float)):
            raise TypeError(f"{point_label}.{axis_name} must be a number")
    return tuple(float(axis_value) for axis_value in candidate_point)


def distance_3d(p1, p2):
    start_point = validate_point(p1, "p1")
    end_point = validate_point(p2, "p2")
    squared_sum = 0.0
    for start_coord, end_coord in zip(start_point, end_point):
        axis_delta = end_coord - start_coord
        squared_sum += axis_delta * axis_delta
    return math.sqrt(squared_sum)


def total_path_length(point_list):
    running_total = 0.0
    for segment_index in range(1, len(point_list)):
        running_total += distance_3d(point_list[segment_index - 1], point_list[segment_index])
    return running_total


def farthest_pair(point_list):
    best_pair = None
    max_distance = 0.0
    for first_index in range(len(point_list)):
        for second_index in range(first_index + 1, len(point_list)):
            current_distance = distance_3d(point_list[first_index], point_list[second_index])
            if best_pair is None or current_distance > max_distance:
                max_distance = current_distance
                best_pair = (point_list[first_index], point_list[second_index])
    return best_pair, max_distance


def format_point(point_tuple):
    coordinate_texts = [f"{axis_value:g}" for axis_value in point_tuple]
    return "(" + ", ".join(coordinate_texts) + ")"


def build_report(point_list):
    report_lines = []
    for segment_index in range(1, len(point_list)):
        previous_point = point_list[segment_index - 1]
        current_point = point_list[segment_index]
        segment_distance = distance_3d(previous_point, current_point)
        report_lines.append(
            f"{format_point(previous_point)} -> {format_point(current_point)}: {segment_distance:.5f}"
        )
    path_length = total_path_length(point_list)
    report_lines.append(f"total path length: {path_length:.5f}")
    (left_point, right_point), max_distance = farthest_pair(point_list)
    report_lines.append(
        f"farthest pair: {format_point(left_point)} and {format_point(right_point)}"
        f" at {max_distance:.5f}"
    )
    return "\n".join(report_lines)


def main():
    sample_points = [(0, 0, 0), (1, 1, 1), (1, 2, 3), (1, 2, 4), (-2, 5, 0.5)]
    print(build_report(sample_points))
    origin_point = (0, 0, 0)
    unit_point = (1, 1, 1)
    unit_distance = distance_3d(origin_point, unit_point)
    print(f"distance_3d({format_point(origin_point)}, {format_point(unit_point)}) ="
          f" {unit_distance}")


if __name__ == "__main__":
