def calculate_factorial_value(input_integer_value):
    if input_integer_value < 0:
        raise ValueError("Factorial is not defined for negative numbers.")
    elif input_integer_value == 0:
        return 1
    else:
        current_product_result = 1
        for i in range(1, input_integer_value + 1):
            current_product_result *= i
        return current_product_result

def compute_factorial_iteratively(number_to_process):
    if number_to_process < 0:
        raise ValueError("Input must be a non-negative integer.")

    if number_to_process == 0:
        return 1

    final_calculated_answer = 1
    for loop_counter_variable in range(1, number_to_process + 1):
        final_calculated_answer *= loop_counter_variable
    return final_calculated_answer

def obtain_factorial_recursively(source_number_for_calculation):
    if source_number_for_calculation < 0:
        raise ValueError("Factorial is not defined for negative inputs.")
    elif source_number_for_calculation == 0:
        return 1
    else:
        recursive_intermediate_result = source_number_for_calculation * obtain_factorial_recursively(source_number_for_calculation - 1)
        return recursive_intermediate_result

