                numericValueOfLastDigit = 10
            else:
                return False
            accumulatedChecksumValue += numericValueOfLastDigit * digitPositionCounter
        digitPositionCounter += 1

    checksumModuloResult = accumulatedChecksumValue % 11
    isChecksumCorrect = checksumModuloResult == 0
    return isChecksumCorrect

