import string
import sys

PUNCTUATION_AND_SPACE = string.punctuation + string.whitespace


def clean_word(raw_word):
    return raw_word.strip(PUNCTUATION_AND_SPACE).lower()


def extract_words(sentence_text):
    if not isinstance(sentence_text, str):
        raise TypeError("sentence must be a string")
    word_list = []
    for raw_token in sentence_text.split():
        cleaned_word = clean_word(raw_token)
        if cleaned_word:
            word_list.append(cleaned_word)
    return word_list


def find_shortest_word(sentence):
    word_list = extract_words(sentence)
    shortest_word = ""
    min_length = None
    for current_word in word_list:
        current_length = len(current_word)
        if min_length is None or current_length < min_length:
            min_length = current_length
            shortest_word = current_word
    return shortest_word


def find_longest_word(sentence):
    word_list = extract_words(sentence)
    longest_word = ""
    max_length = 0
    for current_word in word_list:
        current_length = len(current_word)
        if current_length > max_length:
            max_length = current_length
            longest_word = current_word
    return longest_word


def average_word_length(sentence):
    word_list = extract_words(sentence)
    total_count = len(word_list)
    if total_count == 0:
        return 0.0
    total_length = sum(len(current_word) for current_word in word_list)
    return total_length / total_count


def build_report(sentence):
    word_list = extract_words(sentence)
    report_lines = ["sentence: {!r}".format(sentence),
                    "word count: {}".format(len(word_list))]
    if word_list:
        report_lines.append("shortest word: {!r}".format(find_shortest_word(sentence)))
        report_lines.append("longest word: {!r}".format(find_longest_word(sentence)))
        report_lines.append("average length: {:.2f}".format(average_word_length(sentence)))
    else:
        report_lines.append("no words found")
    return "\n".join(report_lines)


def main():
    for input_line in sys.stdin:
        print(build_report(input_line.rstrip("\n")))
        print("-" * 40)


if __name__ == "__main__":
    main()

